import React from "react";
import {
  FaSearch,
  FaFilter,
  FaTh,
  FaBars,
} from "react-icons/fa";

import FilterModal from "./FilterModalComponent";
import RequestRecords from "./RequestRecordsComponent";

class RequestsPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      activeTab: "waiting",
      search: "",
      viewMode: "card",
      isFilterOpen: false,

      province: "",
      startDate: "",
      endDate: "",
    };

    this.requests = [
      {
        id: 1,
        customerName: "تنبنده",
        deviceType: "ساید",
        deviceBrand: "خاموش",
        technician: "---",
        date: "۱۴۰۵/۰۵/۱۲",
        status: "waiting",
      },
      {
        id: 2,
        customerName: "سبزی",
        deviceType: "پکیج فریزر",
        deviceBrand: "یخچال گرم",
        technician: "---",
        date: "۱۴۰۵/۰۵/۱۸",
        status: "waiting",
      },
      {
        id: 3,
        customerName: "محمدی",
        deviceType: "لباسشویی",
        deviceBrand: "سامسونگ",
        technician: "---",
        date: "۱۴۰۵/۰۵/۲۰",
        status: "confirmed",
      },
      {
        id: 4,
        customerName: "رضایی",
        deviceType: "یخچال",
        deviceBrand: "اسنوا",
        technician: "---",
        date: "۱۴۰۵/۰۵/۲۱",
        status: "confirmed",
      },
    ];
  }

  handleSearchChange = (e) => {
    this.setState({
      search: e.target.value,
    });
  };

  handleTabChange = (tab) => {
    this.setState({
      activeTab: tab,
    });
  };

  handleViewModeChange = (mode) => {
    this.setState({
      viewMode: mode,
    });
  };

  handleOpenFilter = () => {
    this.setState({
      isFilterOpen: true,
    });
  };

  handleCloseFilter = () => {
    this.setState({
      isFilterOpen: false,
    });
  };

  handleProvinceChange = (e) => {
    this.setState({
      province: e.target.value,
    });
  };

  handleStartDateChange = (e) => {
    this.setState({
      startDate: e.target.value,
    });
  };

  handleEndDateChange = (e) => {
    this.setState({
      endDate: e.target.value,
    });
  };

  handleApplyFilter = () => {
    const {
      province,
      startDate,
      endDate,
    } = this.state;

    // ==========================================
    // TODO:
    // بعداً API فیلتر اینجا متصل شود.
    //
    // مثال:
    // api.get("/requests", {
    //   params: {
    //     province,
    //     startDate,
    //     endDate,
    //   }
    // })
    // ==========================================

    console.log("Filter:", {
      province,
      startDate,
      endDate,
    });

    this.setState({
      isFilterOpen: false,
    });
  };

  getFilteredRequests = () => {
    const {
      activeTab,
      search,
    } = this.state;

    return this.requests.filter((request) => {
      const matchesTab =
        request.status === activeTab;

      const searchText = search.trim().toLowerCase();

      const matchesSearch =
        !searchText ||
        request.customerName
          .toLowerCase()
          .includes(searchText) ||
        request.deviceType
          .toLowerCase()
          .includes(searchText) ||
        request.deviceBrand
          .toLowerCase()
          .includes(searchText);

      return matchesTab && matchesSearch;
    });
  };

  render() {
    const {
      activeTab,
      search,
      viewMode,
      isFilterOpen,
      province,
      startDate,
      endDate,
    } = this.state;

    const filteredRequests =
      this.getFilteredRequests();

    return (
      <div className="container">
        {/* ================= Search ================= */}
        <div
          className="position-relative mb-3"
          style={{
            animation: "fadeSlideDown .45s ease",
          }}
        >
          <FaSearch
            className="position-absolute text-secondary"
            style={{
              left: "16px",
              top: "50%",
              transform: "translateY(-50%)",
              zIndex: 2,
            }}
          />

          <input
            type="text"
            value={search}
            onChange={this.handleSearchChange}
            placeholder="جستجو..."
            className="form-control border rounded-pill shadow-none"
            style={{
              height: "58px",
              paddingRight: "20px",
              paddingLeft: "48px",
              fontSize: "15px",
            }}
          />
        </div>

        {/* ================= Tabs ================= */}
        <div
          className="d-flex p-1 mb-4 rounded-pill"
          style={{
            background: "#f5f2ff",
            border: "1px solid #eee9ff",
          }}
        >
          <button
            type="button"
            onClick={() =>
              this.handleTabChange("waiting")
            }
            className="btn flex-grow-1 rounded-pill"
            style={{
              height: "52px",
              background:
                activeTab === "waiting"
                  ? "#ffffff"
                  : "transparent",
              color:
                activeTab === "waiting"
                  ? "#5540a8"
                  : "#aaa",
              border:
                activeTab === "waiting"
                  ? "1px solid #7158c9"
                  : "1px solid transparent",
              transition:
                "all .3s cubic-bezier(.22,1,.36,1)",
            }}
          >
            منتظر تایید تعمیرکار
          </button>

          <button
            type="button"
            onClick={() =>
              this.handleTabChange("confirmed")
            }
            className="btn flex-grow-1 rounded-pill"
            style={{
              height: "52px",
              background:
                activeTab === "confirmed"
                  ? "#ffffff"
                  : "transparent",
              color:
                activeTab === "confirmed"
                  ? "#5540a8"
                  : "#aaa",
              border:
                activeTab === "confirmed"
                  ? "1px solid #7158c9"
                  : "1px solid transparent",
              transition:
                "all .3s cubic-bezier(.22,1,.36,1)",
            }}
          >
            تایید شده
          </button>
        </div>

        {/* ================= Toolbar ================= */}
        <div
          className="d-flex align-items-center justify-content-between mb-2"
        >
 
          {/* Filter */}
          <button
            type="button"
            onClick={this.handleOpenFilter}
            className="btn bg-white border rounded-4 d-flex align-items-center gap-3 px-4"
            style={{
              height: "58px",
              color: "#777",
              transition: "all .25s ease",
            }}
          >
            <span>فیلتر</span>
            <FaFilter size={20} />
          </button>
          <div className="d-flex gap-2">
            {/* List */}
            <button
              type="button"
              onClick={() =>
                this.handleViewModeChange("list")
              }
              className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
              style={{
                width: "58px",
                height: "58px",
                color:
                  viewMode === "list"
                    ? "#4d3ba3"
                    : "#888",
                boxShadow:
                  viewMode === "list"
                    ? "0 4px 14px rgba(80,60,160,.08)"
                    : "none",
                transition: "all .25s ease",
              }}
            >
              <FaBars size={23} />
            </button>

            {/* Grid */}
            <button
              type="button"
              onClick={() =>
                this.handleViewModeChange("card")
              }
              className="btn bg-white border rounded-4 d-flex align-items-center justify-content-center"
              style={{
                width: "58px",
                height: "58px",
                color:
                  viewMode === "card"
                    ? "#4d3ba3"
                    : "#888",
                boxShadow:
                  viewMode === "card"
                    ? "0 4px 14px rgba(80,60,160,.08)"
                    : "none",
                transition: "all .25s ease",
              }}
            >
              <FaTh size={23} />
            </button>
          </div>
        </div>

        {/* ================= Records ================= */}
        <RequestRecords
          records={filteredRequests}
          viewMode={viewMode}
        />

        {/* ================= Filter ================= */}
        <FilterModal
          isOpen={isFilterOpen}
          onClose={this.handleCloseFilter}
          onApply={this.handleApplyFilter}
          province={province}
          startDate={startDate}
          endDate={endDate}
          onProvinceChange={
            this.handleProvinceChange
          }
          onStartDateChange={
            this.handleStartDateChange
          }
          onEndDateChange={
            this.handleEndDateChange
          }
        />

        <style>
          {`
            @keyframes fadeSlideDown {
              from {
                opacity: 0;
                transform: translateY(-10px);
              }

              to {
                opacity: 1;
                transform: translateY(0);
              }
            }
          `}
        </style>
      </div>
    );
  }
}

export default RequestsPage;
